"use strict";(globalThis.webpackChunkgrc||=[]).push([[79104],{54434(e){e.exports=JSON.parse('{"citeKey":"he2016boostingparallel","slug":"he-2016-boosting-parallel-3d56","title":"Boosting Parallel File System Performance with Heterogeneity-Aware Selective Data Layout","authors":["S. He","Y. Wang","X.-H. Sun"],"venue":"IEEE Transactions on Parallel and Distributed Systems (TPDS), 2016. vol. 27, no. 9, pp. 2492-2505","type":"Journal","entryType":"article","date":"September, 2016","year":2016,"era":"iit","month":9,"doi":"10.1109/tpds.2015.2504969","abstract":"Hybrid parallel file systems (PFS) that combine HDD servers with SSD servers provide a promising solution for data intensive applications. The efficiency of a hybrid PFS relies on the data layout schemes. However, most current layout strategies are designed for homogeneous servers, which neither address the heterogeneity of servers nor the varying access patterns of applications. In this paper, we propose HAS, a novel heterogeneity-aware selective data layout scheme for hybrid PFSs. HAS alleviates inter-server load imbalance through skewing data distribution on heterogeneous servers based on their storage performance. Furthermore, to obtain the optimal performance for a specific access pattern, HAS selects one static data layout policy with lowest access cost from three typical layout candidates as the final file data layout method. To adapt to the mixed access patterns within an application, HAS uses a dynamic data layout scheme, which stores file with multiple copies, each using a different data layout policy, and then selects the copy with the lowest access cost to serve file requests. We have implemented HAS within MPICH2 and OrangeFS. Experimental results show that HAS can significantly increase the I/O throughput of hybrid PFSs, compared to existing data layout optimization methods.","hasAbstract":true,"lede":"Hybrid parallel file systems (PFS) that combine HDD servers with SSD servers provide a promising solution for data intensive applications.","links":{"pdf":"https://grc.iit.edu/papers/2016/he-2016-boosting-parallel-3d56.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);